<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Pop Balloons — Windows 95 Archer</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Press+Start+2P&family=Rubik:wght@400;600;800&display=swap" rel="stylesheet">
<style>
  :root{
    --ink:#1b2a3a; --panel:#fdf6e3; --accent:#e63946; --gold:#ffd166;
  }
  *{box-sizing:border-box; margin:0; padding:0;}
  html,body{height:100%; overflow:hidden; background:#0d1b2a; font-family:'Rubik',sans-serif;}
  #wrap{position:relative; width:100vw; height:100vh; display:flex; align-items:center; justify-content:center;
    background:radial-gradient(1200px 700px at 50% 120%, #16324f 0%, #0d1b2a 60%, #060d16 100%);}
  #game{position:relative; width:min(100vw, calc(100vh * 16 / 10)); height:min(100vh, calc(100vw * 10 / 16));
    box-shadow:0 40px 90px rgba(0,0,0,.6), 0 0 0 6px #2b3d52, 0 0 0 10px #101c2a; border-radius:8px; overflow:hidden; cursor:crosshair; background:#7ec8e3;}
  canvas{display:block; width:100%; height:100%;}
  #hud{position:absolute; top:0; left:0; right:0; display:flex; justify-content:space-between; align-items:flex-start;
    padding:14px 18px; pointer-events:none; font-family:'Press Start 2P', monospace;}
  .chip{background:rgba(13,27,42,.72); border:2px solid rgba(255,209,102,.55); border-radius:8px; padding:8px 12px;
    color:#ffe9a8; font-size:12px; line-height:1.5; text-shadow:1px 1px 0 #000;}
  .chip small{display:block; font-family:'Rubik',sans-serif; font-weight:600; letter-spacing:.12em; font-size:9px; color:#9fd8ef; text-transform:uppercase; margin-bottom:2px;}
  #lives{display:flex; gap:6px; margin-top:4px;}
  .heart{font-size:14px; color:#ff5b6a; text-shadow:1px 1px 0 #000; letter-spacing:2px;}
  .heart.off{color:#3a4a5e;}
  #power{position:absolute; left:18px; bottom:18px; width:230px; pointer-events:none; opacity:0; transition:opacity .12s;}
  #power.on{opacity:1;}
  #power .label{font-family:'Press Start 2P'; font-size:10px; color:#fff; text-shadow:1px 1px 0 #000; margin-bottom:6px;}
  #powerBar{height:16px; border:2px solid #fff; border-radius:9px; background:rgba(0,0,0,.35); overflow:hidden;}
  #powerFill{height:100%; width:0%; background:linear-gradient(90deg,#7bd95b,#ffd166 60%,#ff5b3a); transition:width .05s linear;}
  .overlay{position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
    background:rgba(9,17,28,.78); backdrop-filter:blur(4px); text-align:center; z-index:5; transition:opacity .35s;}
  .overlay.hidden{opacity:0; pointer-events:none; visibility:hidden;}
  .overlay h1{font-family:'Press Start 2P'; color:#ffd166; font-size:clamp(22px,4.6vw,44px); line-height:1.5; text-shadow:3px 3px 0 #b3541e, 6px 6px 0 rgba(0,0,0,.4);}
  .overlay p{color:#cfe3ee; font-size:clamp(13px,1.6vw,17px); max-width:560px; line-height:1.6; padding:0 24px;}
  .btn{font-family:'Press Start 2P'; font-size:clamp(12px,1.6vw,16px); color:#1b2a3a; background:linear-gradient(#ffe08a,#ffb347);
    border:0; border-radius:10px; padding:16px 28px; cursor:pointer; box-shadow:0 6px 0 #b3541e, 0 10px 24px rgba(0,0,0,.45);
    transition:transform .08s, box-shadow .08s; letter-spacing:.05em;}
  .btn:hover{transform:translateY(-2px); box-shadow:0 8px 0 #b3541e, 0 14px 28px rgba(0,0,0,.5);}
  .btn:active{transform:translateY(3px); box-shadow:0 2px 0 #b3541e;}
  #finalScore{font-family:'Press Start 2P'; color:#fff; font-size:clamp(16px,2.6vw,26px); text-shadow:2px 2px 0 #000;}
  #finalScore span{color:#ffd166;}
